// ----- Recompensas (ESTANDARES-juegos.md, sección 12) -----
// Se reparten en línea recta entre el tablero más fácil (3×3) y el más difícil (30×30): a más tamaño, más recompensa.
const entre = (n, minimo, maximo) => {
  const t = (Math.min(TAMANO_MAX, Math.max(TAMANO_MIN, n)) - TAMANO_MIN) / (TAMANO_MAX - TAMANO_MIN);
  return Math.round(minimo + (maximo - minimo) * t);
};
// 1) Puntos del PORTAL: 1 por nivel pasado (la primera vez), en cualquier juego. Lo aplica encolarNivel() de compartido/cola-puntos.js.
// 2) Monedas de este juego: de 15 (3×3) a 80 (30×30) por nivel pasado. Se pagan UNA sola vez por nivel; el modo libre no da monedas.
export const monedasDe = (n) => entre(n, 15, 80);
// 3) Puntos del JUEGO (el marcador de dentro del juego): de 80 (3×3) a 250 (30×30) por cada partida ganada (niveles y modo libre).
export const puntosJuegoDe = (n) => entre(n, 80, 250);
